window.AUTH=window.AUTH||{};window.AUTH["22-340"]={"d":"22-340","id":"2023/22-340","n":"Pulsifer v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Mark E. Pulsifer","date":"2023-05-19","url":"https://www.supremecourt.gov/DocketPDF/22/22-340/267269/20230519142156758_Pulsifer%20v.%20United%20States%20Merits%20Brief%20FILE.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondent United States","date":"2023-07-24","url":"https://www.supremecourt.gov/DocketPDF/22/22-340/272805/20230724211315733_22-340bsUnitedStates.pdf","side":"res","n":93},{"k":"reply","label":"Reply of petitioner Mark E. Pulsifer","date":"2023-08-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-340/276008/20230823133339428_Pulsifer%20v.%20United%20States%20Reply%20Brief%20for%20Petitioner%20FILE.pdf","side":"pet","n":47}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r07_19m1.pdf","tr":true,"items":[{"t":"case","label":"62 Cases of Jam v. United States","cite":"340 U.S. 593","y":1951,"id":"scdb/1950-050","sc":1,"op":3,"sum":"It was not \"misbranded\" within the meaning of § 403. Federal Security Administrator v. Quaker Oats Co., 318 U. S. 218, distinguished. Pp. 593-601. 183 F. 2d 1014, reversed. On a libel by the United States against certain food products under § 304 of the Federal Food, Drug, and Cosmetic Act, the District Court held that they were not \"misbranded\" within the meaning of § 403. 87 F. Supp. 735. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","2":"11"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"0":"17, 20"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"op":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 48","1":"46"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"0":"12, 13, 20, 21, 29","1":"30, 42","2":"14"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"0":"43, 48, 49","2":"22"}},{"t":"case","label":"Callanan v. United States","cite":"364 U.S. 587","y":1961,"id":"1960/47","sc":1,"sum":"Under the Act, obstructing interstate commerce by extortion and conspiring to do so are separate offenses; separate consecutive sentences may be imposed for each offense. Pp. 587-597. 274 F. 2d 601, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Concepcion v. United States","cite":"142 S. Ct. 2389","y":2022,"id":"2021/20-1650","sc":1,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 24, 25","2":"3, 20"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 34"}},{"t":"case","label":"Crooks v. Harrelson","cite":"282 U.S. 55","y":1930,"id":"scdb/1930-011","sc":1,"sum":"that the requirements that a property interest, to be included, shall be subject to the payment of the charges against the estate and the expenses of administration must be taken, as they are expressed, in the conjunctive; that charges against the estate and expenses of administration are different and distinct things, and that when, by the state law, an interest in real estate, though subject to the former, is not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"36"}},{"t":"case","label":"Cyan, Inc. v. Beaver County Employees Retirement Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"op":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"27, 33","2":"11"}},{"t":"case","label":"HollyFrontier Cheyenne Refining, LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Koons Buick Pontiac GMC, Inc. v. Nigh","cite":"543 U.S. 50","y":2004,"id":"2004/03-377","sc":1,"sum":"In an 8-1 judgment delivered by Justice Ruth Bader Ginsburg, the Court held that a 1995 TILA amendment did not change the original limit on violations involving personal-property loans. Congress intended the amendment to raise the minimum and maximum recoveries for closed-end loans secured by real property. Congress had not sought to remove the $1,000 cap on loans secured by personal property.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"34, 35","2":"3, 17"}},{"t":"case","label":"Logan v. United States","cite":"552 U.S. 23","y":2007,"id":"2007/06-6911","sc":1,"sum":"The Court, in a unanimous opinion authored by Justice Ruth Bader Ginsburg, affirmed the Seventh Circuit and held that the ACCA amendment should be read literally and should apply only when civil rights had been rescinded and later restored.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"op":1,"sum":"Rejecting an argument that would “disregard what `or' customarily means”.","sumSrc":"opinion","by":{"0":"34, 35","1":"33"}},{"t":"case","label":"Lynch v. Alworth-Stephens Co.","cite":"267 U.S. 364","y":1925,"id":"scdb/1924-237","sc":1,"op":1,"by":{"0":"17, 20, 26"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"34, 35","2":"17"}},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"sum":"A person who receives genuine vehicle titles, knowing that they incorporate fraudulently tendered odometer readings, receives those titles knowing them to have been \"falsely made\" in violation of § 2314.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48","1":"48"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"op":2,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45","2":"3, 6, 21"}},{"t":"case","label":"Public Citizen v. United States Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"op":2,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Rimini Street, Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"op":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"142 S. Ct. 1783","y":2022,"id":"2021/21-309","sc":1,"op":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 33, 42","1":"42","2":"16"}},{"t":"case","label":"United States v. Atlantic Research Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"sum":"The Court ruled unanimously that Section 107(a) of CERCLA allows potentially responsible parties (PRPs) to sue other PRPs for cost recovery. The opinion by Justice Clarence Thomas affirmed the Eighth Circuit and ruled for Atlantic Research.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"United States v. Garcon","cite":"54 F.4th 1274","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/54/1274/","op":5,"ar":5,"by":{"0":"40, 41, 42, 44, 45, 46, 49","1":"44","2":"3"}},{"t":"case","label":"United States v. Haynes","cite":"55 F.4th 1075","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/1075/","op":2,"by":{"0":"11, 37, 40, 44","1":"21, 22, 36, 43"}},{"t":"case","label":"United States v. Jones","cite":"60 F.4th 230","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/230/","op":2,"sum":"Holding that a defendant is eligible for relief so long as he does not have any one of the items listed.","sumSrc":"opinion","by":{"0":"35, 37, 40, 43, 44","2":"14, 15"}},{"t":"case","label":"United States v. Lopez","cite":"998 F.3d 431","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/998/431/","op":4,"ar":3,"by":{"0":"25, 29, 35, 44, 49","1":"35, 45","2":"11"}},{"t":"case","label":"United States v. Pace","cite":"48 F.4th 741","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/741/","op":5,"by":{"0":"39, 41, 44, 46, 47","1":"26","2":"12"}},{"t":"case","label":"United States v. Palomares","cite":"52 F.4th 640","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/52/640/","op":2,"by":{"0":"35, 37, 44, 46, 49","2":"12, 13, 17"}},{"t":"case","label":"United States v. Palomar-Santiago","cite":"141 S. Ct. 1615","y":2021,"id":"2020/20-437","sc":1,"op":1,"sum":"Each of 8 U. S. C. §1326(d)’s statutory requirements for bringing a collateral attack on a prior deportation order is mandatory.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18"}},{"t":"case","label":"United States v. Wiltberger","cite":"5 Wheat. 76","y":1820,"url":"https://www.courtlistener.com/c/Wheat./5/76/","op":3,"ar":1,"by":{"0":"48"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"op":4,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47, 48, 49"}},{"t":"usc","label":"18 U.S.C. § 845","url":"https://www.law.cornell.edu/uscode/text/18/845","subs":["(a)"],"stext":{"head":"§845. Exceptions; relief from disabilities","paras":[[0,"(a) Except in the case of subsection (l), (m), (n), or (o) of section 842 and subsections (d), (e), (f), (g), (h), and (i) of section 844 of this title, this chapter shall not apply to:"],[1,"(1) aspects of the transportation of explosive materials via railroad, water, highway, or air that pertain to safety, including security, and are regulated by the Department of Transportation or the Department of Homeland Security;"],[1,"(2) the use of explosive materials in medicines and medicinal agents in the forms prescribed by the official United States Pharmacopeia, or the National Formulary;"],[1,"(3) the transportation, shipment, receipt, or importation of explosive materials for delivery to any agency of the United States or to any State or political subdivision thereof;"],[1,"(4) small arms ammunition and components thereof;"],[1,"(5) commercially manufactured black powder in quantities not to exceed fifty pounds, percussion caps, safety and pyrotechnic fuses, quills, quick and slow matches, and friction primers, intended to be used solely for sporting, recreational, or cultural purposes in antique firearms as defined in section 921(a)(16) of title 18 of the United States Code, or in antique devices as exempted from the term \"destructive device\" in section 921(a)(4) of title 18 of the United States Code;"],[1,"(6) the manufacture under the regulation of the military department of the United States of explosive materials for, or their distribution to or storage or possession by the military or naval services or other agencies of the United States; or to arsenals, navy yards, depots, or other establishments owned by, or operated by or on behalf of, the United States 1 and"],[1,"(7) the transportation, shipment, receipt, or importation of display fireworks materials for delivery to a federally recognized Indian tribe or tribal agency."],[0,"(b)(1) A person who is prohibited from shipping, transporting, receiving, or possessing any explosive under section 842(i) may apply to the Attorney General for relief from such prohibition."],[0,"(2) The Attorney General may grant the relief requested under paragraph (1) if the Attorney General determines that the circumstances regarding the applicability of section 842(i), and the applicant's record and reputation, are such that the applicant will not be likely to act in a manner dangerous to public safety and that the granting of such relief is not contrary to the public interest."],[0,"(3) A licensee or permittee who applies for relief, under this subsection, from the disabilities incurred under this chapter as a result of an indictment for or conviction of a crime punishable by imprisonment for a term exceeding 1 year shall not be barred by such disability from further operations under the license or permit pending final action on an application for relief filed pursuant to this section."],[0,"(c) It is an affirmative defense against any proceeding involving subsections (l) through (o) of section 842 if the proponent proves by a preponderance of the evidence that the plastic explosive—"],[1,"(1) consisted of a small amount of plastic explosive intended for and utilized solely in lawful—"],[2,"(A) research, development, or testing of new or modified explosive materials;"],[2,"(B) training in explosives detection or development or testing of explosives detection equipment; or"],[2,"(C) forensic science purposes; or"],[1,"(2) was plastic explosive that, within 3 years after the date of enactment of the Antiterrorism and Effective Death Penalty Act of 1996, will be or is incorporated in a military device within the territory of the United States and remains an integral part of such military device, or is intended to be, or is incorporated in, and remains an integral part of a military device that is intended to become, or has become, the property of any agency of the United States performing military or police functions (including any military reserve component) or the National Guard of any State, wherever such device is located."],[1,"(3) For purposes of this subsection, the term \"military device\" includes, but is not restricted to, shells, bombs, projectiles, mines, missiles, rockets, shaped charges, grenades, perforators, and similar devices lawfully manufactured exclusively for military or police purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/845?type=usc&year=mostrecent&link-type=html"},"head":"§845. Exceptions; relief from disabilities","tname":"Crimes and Criminal Procedure","by":{"0":"47","1":"40","2":"20"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(f)","(f)(1)","(f)(1)(2017)","(f)(1)(A)","(f)(1)(B)","(f)(1)(C)","(f)(2)","(f)(2)(C)","(f)(3)","(f)(4)","(f)(5)","(a)(4)","(g)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"13, 23, 25, 29, 30, 31, 40, 41, 45, 47, 35, 36, 40, 42, 43, 44, 45, 46, 47, 49, 50, 8, 42, 37, 38, 39, 40, 41, 42, 44, 45, 46, 50, 33, 35, 36, 38, 41, 42, 44, 45, 46, 50, 6, 8, 9, 21, 24, 25, 29, 30, 31, 45, 25, 21, 24, 25, 29, 30, 31, 45, 21, 24, 25, 29, 30, 31, 45, 21, 24, 25, 29, 30, 31, 45","1":"32, 41, 41, 41, 41, 41, 41, 41, 41, 41","2":"13, 14, 15, 23, 17, 18, 19, 20, 21, 22, 23, 24, 17, 18, 19, 20, 24, 17, 18, 19, 20, 21, 24, 17, 18, 19, 20, 24, 1, 12, 13, 14, 15, 20, 1, 12, 13, 14, 15, 20, 1, 12, 13, 14, 15, 20, 1, 12, 13, 14, 15, 20"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)","(b)(1)(A)(viii)","(b)(1)(A)(v)","(b)(1)(B)","(b)(1)(B)(viii)","(b)(1)(B)(v)","(b)(1)(C)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"8","1":"4, 22, 46, 3, 7, 3, 7, 22, 4, 4, 4, 7, 4, 4, 4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"usc","label":"41 U.S.C. § 6702","url":"https://www.law.cornell.edu/uscode/text/41/6702","subs":["(b)"],"stext":{"head":"§6702. Contracts to which this chapter applies","paras":[[0,"(a) In General.—Except as provided in subsection (b), this chapter applies to any contract or bid specification for a contract, whether negotiated or advertised, that—"],[1,"(1) is made by the Federal Government or the District of Columbia;"],[1,"(2) involves an amount exceeding $2,500; and"],[1,"(3) has as its principal purpose the furnishing of services in the United States through the use of service employees."],[0,"(b) Exemptions.—This chapter does not apply to—"],[1,"(1) a contract of the Federal Government or the District of Columbia for the construction, alteration, or repair, including painting and decorating, of public buildings or public works;"],[1,"(2) any work required to be done in accordance with chapter 65 of this title;"],[1,"(3) a contract for the carriage of freight or personnel by vessel, airplane, bus, truck, express, railway line or oil or gas pipeline where published tariff rates are in effect;"],[1,"(4) a contract for the furnishing of services by radio, telephone, telegraph, or cable companies, subject to the Communications Act of 1934 (47 U.S.C. 151 et seq.);"],[1,"(5) a contract for public utility services, including electric light and power, water, steam, and gas;"],[1,"(6) an employment contract providing for direct services to a Federal agency by an individual; and"],[1,"(7) a contract with the United States Postal Service, the principal purpose of which is the operation of postal contract stations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/41/6702?type=usc&year=mostrecent&link-type=html"},"head":"§6702. Contracts to which this chapter applies","tname":"Public Contracts","by":{"0":"47","1":"41"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"8","1":"5"}},{"t":"case","label":"Abbott v. United States","cite":"562 U.S. 8","y":2010,"id":"2010/09-479","sc":1,"ar":1,"sum":"The Court held that a defendant who receives a mandatory minimum sentence for using or carrying a firearm in furtherance of a drug trafficking crime can serve that sentence consecutively with any other term of imprisonment.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21","2":"15, 16"}},{"t":"case","label":"Bray v. The Atalanta","cite":"4 F. Cas. 37","y":1794,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Cas./4/37/","by":{"1":"46"}},{"t":"case","label":"Caron v. United States","cite":"524 U.S. 308","y":1998,"id":"1997/97-6270","sc":1,"sum":"The Court held that \"Massachusetts treats [Caron] as too dangerous to trust with handguns, though it accords this right to law-abiding citizens.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"City of Chicago v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"op":3,"sum":"The mere retention of estate property after the filing of a bankruptcy petition does not violate 11 U. S. C. §362(a)(3), which operates as a “stay” of “any act” to “exercise control” over the property of the estate.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Commonwealth v. Martin","cite":"17 Mass. 359","y":1821,"url":"https://www.courtlistener.com/c/Mass./17/359/","by":{"1":"46"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"op":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"General Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Graham County Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"sum":"The Court ruled that the six-year statute of limitations did not apply to suits for retaliation. The majority opinion by Justice Clarence Thomas found the statute of limitations \"ambiguous.\" The ambiguity arose from the fact that the six-year limitation in the FCA starts from the time the false claim was made. Yet in a retaliation suit, no actual false claim needs to be alleged.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Hubbard v. United States","cite":"514 U.S. 695","y":1995,"id":"1994/94-172","sc":1,"sum":"The judgment is reversed in part. 16 F. 3d 694, reversed in part. JUSTICE STEVENS delivered the opinion of the Court with respect to Parts I, II, III, and VI, concluding that, because a federal court is neither a \"department\" nor an \"agency\" within § 1001's meaning, the statute does not apply to false statements made in judicial proceedings. Pp. 699-708, 715.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Lockhart v. United States","cite":"577 U.S. 347","y":2016,"id":"2015/14-8358","sc":1,"sum":"The Court determined that a prior conviction of “aggravated sexual abuse” or “sexual abuse” may trigger a mandatory minimum sentence, even when the prior conviction did not involve a minor.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Luna Perez v. Sturgis Pub. Schs.","cite":"143 S. Ct. 859","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/859/","sc":1,"op":4,"by":{"1":"44"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Ohio Adjutant General’s Dep’t v. Federal Labor Relations Auth.","cite":"143 S. Ct. 1193","y":2023,"id":"2022/21-1454","sc":1,"op":1,"sum":"The Federal Labor Relations Authority had jurisdiction over this labor dispute because a State National Guard acts as a federal agency for purposes of the Federal Service Labor-Management Relations Statute, 5 U. S. C. §7101 et seq., when it hires and supervises dual-status technicians serving in their civilian role.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"1":"11, 19"}},{"t":"case","label":"Scialabba v. Cuellar de Osorio","cite":"573 U.S. 41","y":2014,"id":"2013/12-930","sc":1,"sum":"The Court held that the Immigration and Nationality Act does not allow children who have submitted an application for a visa to keep their original application date if they \"aged out\" before it was processed.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Shaw v. National Union Fire Ins. Co. of Pittsburgh","cite":"605 F.3d 1250","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/605/1250/","by":{"1":"15"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"United States v. Angelos","cite":"345 F. Supp. 2d 1227","y":2004,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/345/1227/","sum":"Noting that the defendant “carried a handgun to two $350 marijuana deals”.","sumSrc":"brief:1","by":{"1":"44"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. One 1973 Rolls Royce","cite":"43 F.3d 794","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/43/794/","by":{"1":"26"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"const","label":"Article III, Section 2, Clause 1","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects.","by":{"1":"40","2":"8"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1985","by":{"1":"5"}},{"t":"usc","label":"2 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/2/1602","subs":["(8)(B)"],"stext":{"head":"§1602. Definitions","paras":[[0,"As used in this chapter:"],[0,"(1) Agency"],[1,"The term \"agency\" has the meaning given that term in section 551(1) of title 5."],[0,"(2) Client"],[1,"The term \"client\" means any person or entity that employs or retains another person for financial or other compensation to conduct lobbying activities on behalf of that person or entity. A person or entity whose employees act as lobbyists on its own behalf is both a client and an employer of such employees. In the case of a coalition or association that employs or retains other persons to conduct lobbying activities, the client is the coalition or association and not its individual members."],[0,"(3) Covered executive branch official"],[1,"The term \"covered executive branch official\" means—"],[2,"(A) the President;"],[2,"(B) the Vice President;"],[2,"(C) any officer or employee, or any other individual functioning in the capacity of such an officer or employee, in the Executive Office of the President;"],[2,"(D) any officer or employee serving in a position in level I, II, III, IV, or V of the Executive Schedule, as designated by statute or Executive order;"],[2,"(E) any member of the uniformed services whose pay grade is at or above O–7 under section 201 of title 37; and"],[2,"(F) any officer or employee serving in a position of a confidential, policy-determining, policy-making, or policy-advocating character described in section 7511(b)(2)(B) of title 5."],[0,"(4) Covered legislative branch official"],[1,"The term \"covered legislative branch official\" means—"],[2,"(A) a Member of Congress;"],[2,"(B) an elected officer of either House of Congress;"],[2,"(C) any employee of, or any other individual functioning in the capacity of an employee of—"],[3,"(i) a Member of Congress;"],[3,"(ii) a committee of either House of Congress;"],[3,"(iii) the leadership staff of the House of Representatives or the leadership staff of the Senate;"],[3,"(iv) a joint committee of Congress; and"],[3,"(v) a working group or caucus organized to provide legislative services or other assistance to Members of Congress; and"],[2,"(D) any other legislative branch employee serving in a position described under section 13101(13) of title 5."],[0,"(5) Employee"],[1,"The term \"employee\" means any individual who is an officer, employee, partner, director, or proprietor of a person or entity, but does not include—"],[2,"(A) independent contractors; or"],[2,"(B) volunteers who receive no financial or other compensation from the person or entity for their services."],[0,"(6) Foreign entity"],[1,"The term \"foreign entity\" means a foreign principal (as defined in section 1(b) of the Foreign Agents Registration Act of 1938 (22 U.S.C. 611(b))."],[0,"(7) Lobbying activities"],[1,"The term \"lobbying activities\" means lobbying contacts and efforts in support of such contacts, including preparation and planning activities, research and other background work that is intended, at the time it is performed, for use in contacts, and coordination with the lobbying activities of others."],[0,"(8) Lobbying contact"],[0,"(A) Definition"],[2,"The term \"lobbying contact\" means any oral or written communication (including an electronic communication) to a covered executive branch official or a covered legislative branch official that is made on behalf of a client with regard to—"],[3,"(i) the formulation, modification, or adoption of Federal legislation (including legislative proposals);"],[3,"(ii) the formulation, modification, or adoption of a Federal rule, regulation, Executive order, or any other program, policy, or position of the United States Government;"],[3,"(iii) the administration or execution of a Federal program or policy (including the negotiation, award, or administration of a Federal contract, grant, loan, permit, or license); or"],[3,"(iv) the nomination or confirmation of a person for a position subject to confirmation by the Senate."],[0,"(B) Exceptions"],[2,"The term \"lobbying contact\" does not include a communication that is—"],[3,"(i) made by a public official acting in the public official's official capacity;"],[3,"(ii) made by a representative of a media organization if the purpose of the communication is gathering and disseminating news and information to the public;"],[3,"(iii) made in a speech, article, publication or other material that is distributed and made available to the public, or through radio, television, cable television, or other medium of mass communication;"],[3,"(iv) made on behalf of a government of a foreign country or a foreign political party and disclosed under the Foreign Agents Registration Act of 1938 (22 U.S.C. 611 et seq.);"],[3,"(v) a request for a meeting, a request for the status of an action, or any other similar administrative request, if the request does not include an attempt to influence a covered executive branch official or a covered legislative branch official;"],[3,"(vi) made in the course of participation in an advisory committee subject to chapter 10 of title 5;"],[3,"(vii) testimony given before a committee, subcommittee, or task force of the Congress, or submitted for inclusion in the public record of a hearing conducted by such committee, subcommittee, or task force;"],[3,"(viii) information provided in writing in response to an oral or written request by a covered executive branch official or a covered legislative branch official for specific information;"],[3,"(ix) required by subpoena, civil investigative demand, or otherwise compelled by statute, regulation, or other action of the Congress or an agency, including any communication compelled by a Federal contract, grant, loan, permit, or license;"],[3,"(x) made in response to a notice in the Federal Register, Commerce Business Daily, or other similar publication soliciting communications from the public and directed to the agency official specifically designated in the notice to receive such communications;"],[3,"(xi) not possible to report without disclosing information, the unauthorized disclosure of which is prohibited by law;"],[3,"(xii) made to an official in an agency with regard to—"],[4,"(I) a judicial proceeding or a criminal or civil law enforcement inquiry, investigation, or proceeding; or"],[4,"(II) a filing or proceeding that the Government is specifically required by statute or regulation to maintain or conduct on a confidential basis,"],[0,"if that agency is charged with responsibility for such proceeding, inquiry, investigation, or filing;"],[3,"(xiii) made in compliance with written agency procedures regarding an adjudication conducted by the agency under section 554 of title 5 or substantially similar provisions;"],[3,"(xiv) a written comment filed in the course of a public proceeding or any other communication that is made on the record in a public proceeding;"],[3,"(xv) a petition for agency action made in writing and required to be a matter of public record pursuant to established agency procedures;"],[3,"(xvi) made on behalf of an individual with regard to that individual's benefits, employment, or other personal matters involving only that individual, except that this clause does not apply to any communication with—"],[4,"(I) a covered executive branch official, or"],[4,"(II) a covered legislative branch official (other than the individual's elected Members of Congress or employees who work under such Members' direct supervision),"],[0,"with respect to the formulation, modification, or adoption of private legislation for the relief of that individual;"],[3,"(xvii) a disclosure by an individual that is protected under the amendments made by the Whistleblower Protection Act of 1989, under chapter 4 of title 5, or under another provision of law;"],[3,"(xviii) made by—"],[4,"(I) a church, its integrated auxiliary, or a convention or association of churches that is exempt from filing a Federal income tax return under paragraph 2(A)(i) of section 6033(a) of title 26, or"],[4,"(II) a religious order that is exempt from filing a Federal income tax return under paragraph (2)(A)(iii) of such section 6033(a); and"],[3,"(xix) between—"],[4,"(I) officials of a self-regulatory organization (as defined in section 3(a)(26) of the Securities Exchange Act [15 U.S.C. 78c(a)(26)]) that is registered with or established by the Securities and Exchange Commission as required by that Act [15 U.S.C. 78a et seq.] or a similar organization that is designated by or registered with the Commodities Future Trading Commission as provided under the Commodity Exchange Act [7 U.S.C. 1 et seq.]; and"],[4,"(II) the Securities and Exchange Commission or the Commodities Future Trading Commission, respectively;"],[0,"relating to the regulatory responsibilities of such organization under that Act."],[0,"(9) Lobbying firm"],[1,"The term \"lobbying firm\" means a person or entity that has 1 or more employees who are lobbyists on behalf of a client other than that person or entity. The term also includes a self-employed individual who is a lobbyist."],[0,"(10) Lobbyist"],[1,"The term \"lobbyist\" means any individual who is employed or retained by a client for financial or other compensation for services that include more than one lobbying contact, other than an individual whose lobbying activities constitute less than 20 percent of the time engaged in the services provided by such individual to that client over a 3-month period."],[0,"(11) Media organization"],[1,"The term \"media organization\" means a person or entity engaged in disseminating information to the general public through a newspaper, magazine, other publication, radio, television, cable television, or other medium of mass communication."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/1602?type=usc&year=mostrecent&link-type=html"},"head":"§1602. Definitions","tname":"The Congress","by":{"1":"40","2":"20"}},{"t":"usc","label":"5 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/5/105","stext":{"head":"§105. Executive agency","paras":[[0,"For the purpose of this title, \"Executive agency\" means an Executive department, a Government corporation, and an independent establishment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/105?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§105. Executive agency","tname":"Government Organization and Employees","by":{"1":"17, 41","2":"8"}},{"t":"usc","label":"18 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/18/202","subs":["(d)"],"stext":{"head":"§202. Definitions","paras":[[0,"(a) For the purpose of sections 203, 205, 207, 208, and 209 of this title the term \"special Government employee\" shall mean an officer or employee of the executive or legislative branch of the United States Government, of any independent agency of the United States or of the District of Columbia, who is retained, designated, appointed, or employed to perform, with or without compensation, for not to exceed one hundred and thirty days during any period of three hundred and sixty-five consecutive days, temporary duties either on a full-time or intermittent basis, a part-time United States commissioner, a part-time United States magistrate judge, or, regardless of the number of days of appointment, an independent counsel appointed under chapter 40 of title 28 and any person appointed by that independent counsel under section 594(c) of title 28. Notwithstanding the next preceding sentence, every person serving as a part-time local representative of a Member of Congress in the Member's home district or State shall be classified as a special Government employee. Notwithstanding sections 502, 2105(d), and 5534 of title 5, a Reserve officer of the Armed Forces, an officer of the Space Force not serving on sustained duty pursuant to section 20105 of title 10, or an officer of the National Guard of the United States, unless otherwise an officer or employee of the United States, shall be classified as a special Government employee while on active duty solely for training. Such an officer who is voluntarily serving a period of extended active duty in excess of one hundred and thirty days shall be classified as an officer of the United States within the meaning of section 203 and sections 205 through 209 and 218. Such an officer who is serving involuntarily shall be classified as a special Government employee. The terms \"officer or employee\" and \"special Government employee\" as used in sections 203, 205, 207 through 209, and 218, shall not include enlisted members of the Armed Forces."],[0,"(b) For the purposes of sections 205 and 207 of this title, the term \"official responsibility\" means the direct administrative or operating authority, whether intermediate or final, and either exercisable alone or with others, and either personally or through subordinates, to approve, disapprove, or otherwise direct Government action."],[0,"(c) Except as otherwise provided in such sections, the terms \"officer\" and \"employee\" in sections 203, 205, 207 through 209, and 218 of this title shall not include the President, the Vice President, a Member of Congress, or a Federal judge."],[0,"(d) The term \"Member of Congress\" in sections 204 and 207 means—"],[1,"(1) a United States Senator; and"],[1,"(2) a Representative in, or a Delegate or Resident Commissioner to, the House of Representatives."],[0,"(e) As used in this chapter, the term—"],[1,"(1) \"executive branch\" includes each executive agency as defined in title 5, and any other entity or administrative unit in the executive branch;"],[1,"(2) \"judicial branch\" means the Supreme Court of the United States; the United States courts of appeals; the United States district courts; the Court of International Trade; the United States bankruptcy courts; any court created pursuant to article I of the United States Constitution, including the Court of Appeals for the Armed Forces, the United States Court of Federal Claims, and the United States Tax Court, but not including a court of a territory or possession of the United States; the Federal Judicial Center; and any other agency, office, or entity in the judicial branch; and"],[1,"(3) \"legislative branch\" means—"],[2,"(A) the Congress; and"],[2,"(B) the Office of the Architect of the Capitol, the United States Botanic Garden, the Government Accountability Office, the Government Publishing Office, the Library of Congress, the Office of Technology Assessment, the Congressional Budget Office, the United States Capitol Police, and any other agency, entity, office, or commission established in the legislative branch."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/202?type=usc&year=mostrecent&link-type=html"},"head":"§202. Definitions","tname":"Crimes and Criminal Procedure","by":{"1":"40","2":"20"}},{"t":"usc","label":"18 U.S.C. § 212","url":"https://www.law.cornell.edu/uscode/text/18/212","subs":["(c)(2)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 229A","url":"https://www.law.cornell.edu/uscode/text/18/229A","subs":["(c)"],"by":{"1":"40, 41"}},{"t":"usc","label":"18 U.S.C. § 232","url":"https://www.law.cornell.edu/uscode/text/18/232","subs":["(5)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/18/341","by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/18/601","subs":["(b)(2)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)"],"by":{"1":"44"}},{"t":"usc","label":"18 U.S.C. § 925","url":"https://www.law.cornell.edu/uscode/text/18/925","subs":["(a)(2)"],"stext":{"head":"§925. Exceptions: Relief from disabilities","paras":[[0,"(a)(1) The provisions of this chapter, except for sections 922(d)(9) and 922(g)(9) and provisions relating to firearms subject to the prohibitions of section 922(p), shall not apply with respect to the transportation, shipment, receipt, possession, or importation of any firearm or ammunition imported for, sold or shipped to, or issued for the use of, the United States or any department or agency thereof or any State or any department, agency, or political subdivision thereof."],[0,"(2) The provisions of this chapter, except for provisions relating to firearms subject to the prohibitions of section 922(p), shall not apply with respect to (A) the shipment or receipt of firearms or ammunition when sold or issued by the Secretary of the Army pursuant to section 4308 of title 10 before the repeal of such section by section 1624(a) of the Corporation for the Promotion of Rifle Practice and Firearms Safety Act, and (B) the transportation of any such firearm or ammunition carried out to enable a person, who lawfully received such firearm or ammunition from the Secretary of the Army, to engage in military training or in competitions."],[0,"(3) Unless otherwise prohibited by this chapter, except for provisions relating to firearms subject to the prohibitions of section 922(p), or any other Federal law, a licensed importer, licensed manufacturer, or licensed dealer may ship to a member of the United States Armed Forces on active duty outside the United States or to clubs, recognized by the Department of Defense, whose entire membership is composed of such members, and such members or clubs may receive a firearm or ammunition determined by the Attorney General to be generally recognized as particularly suitable for sporting purposes and intended for the personal use of such member or club."],[0,"(4) When established to the satisfaction of the Attorney General to be consistent with the provisions of this chapter, except for provisions relating to firearms subject to the prohibitions of section 922(p), and other applicable Federal and State laws and published ordinances, the Attorney General may authorize the transportation, shipment, receipt, or importation into the United States to the place of residence of any member of the United States Armed Forces who is on active duty outside the United States (or who has been on active duty outside the United States within the sixty day period immediately preceding the transportation, shipment, receipt, or importation), of any firearm or ammunition which is (A) determined by the Attorney General to be generally recognized as particularly suitable for sporting purposes, or determined by the Department of Defense to be a type of firearm normally classified as a war souvenir, and (B) intended for the personal use of such member."],[0,"(5) For the purpose of paragraph (3) of this subsection, the term \"United States\" means each of the several States and the District of Columbia."],[0,"(b) A licensed importer, licensed manufacturer, licensed dealer, or licensed collector who is indicted for a crime punishable by imprisonment for a term exceeding one year, may, notwithstanding any other provision of this chapter, continue operation pursuant to his existing license (if prior to the expiration of the term of the existing license timely application is made for a new license) during the term of such indictment and until any conviction pursuant to the indictment becomes final."],[0,"(c) A person who is prohibited from possessing, shipping, transporting, or receiving firearms or ammunition may make application to the Attorney General for relief from the disabilities imposed by Federal laws with respect to the acquisition, receipt, transfer, shipment, transportation, or possession of firearms, and the Attorney General may grant such relief if it is established to his satisfaction that the circumstances regarding the disability, and the applicant's record and reputation, are such that the applicant will not be likely to act in a manner dangerous to public safety and that the granting of the relief would not be contrary to the public interest. Any person whose application for relief from disabilities is denied by the Attorney General may file a petition with the United States district court for the district in which he resides for a judicial review of such denial. The court may in its discretion admit additional evidence where failure to do so would result in a miscarriage of justice. A licensed importer, licensed manufacturer, licensed dealer, or licensed collector conducting operations under this chapter, who makes application for relief from the disabilities incurred under this chapter, shall not be barred by such disability from further operations under his license pending final action on an application for relief filed pursuant to this section. Whenever the Attorney General grants relief to any person pursuant to this section he shall promptly publish in the Federal Register notice of such action, together with the reasons therefor."],[0,"(d) The Attorney General shall authorize a firearm or ammunition to be imported or brought into the United States or any possession thereof if the firearm or ammunition—"],[1,"(1) is being imported or brought in for scientific or research purposes, or is for use in connection with competition or training pursuant to chapter 751 of title 10;"],[1,"(2) is an unserviceable firearm, other than a machinegun as defined in section 5845(b) of the Internal Revenue Code of 1986 (not readily restorable to firing condition), imported or brought in as a curio or museum piece;"],[1,"(3) is of a type that does not fall within the definition of a firearm as defined in section 5845(a) of the Internal Revenue Code of 1986 and is generally recognized as particularly suitable for or readily adaptable to sporting purposes, excluding surplus military firearms, except in any case where the Attorney General has not authorized the importation of the firearm pursuant to this paragraph, it shall be unlawful to import any frame, receiver, or barrel of such firearm which would be prohibited if assembled; or"],[1,"(4) was previously taken out of the United States or a possession by the person who is bringing in the firearm or ammunition."],[0,"The Attorney General shall permit the conditional importation or bringing in of a firearm or ammunition for examination and testing in connection with the making of a determination as to whether the importation or bringing in of such firearm or ammunition will be allowed under this subsection."],[0,"(e) Notwithstanding any other provision of this title, the Attorney General shall authorize the importation of, by any licensed importer, the following:"],[1,"(1) All rifles and shotguns listed as curios or relics by the Attorney General pursuant to section 921(a)(13), and"],[1,"(2) All handguns, listed as curios or relics by the Attorney General pursuant to section 921(a)(13), provided that such handguns are generally recognized as particularly suitable for or readily adaptable to sporting purposes."],[0,"(f) The Attorney General shall not authorize, under subsection (d), the importation of any firearm the importation of which is prohibited by section 922(p)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/925?type=usc&year=mostrecent&link-type=html"},"head":"§925. Exceptions: Relief from disabilities","tname":"Crimes and Criminal Procedure","by":{"1":"40","2":"20"}},{"t":"usc","label":"18 U.S.C. § 926B","url":"https://www.law.cornell.edu/uscode/text/18/926B","subs":["(e)(3)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/18/1963","subs":["(h)"],"stext":{"head":"§1963. Criminal penalties","paras":[[0,"(a) Whoever violates any provision of section 1962 of this chapter shall be fined under this title or imprisoned not more than 20 years (or for life if the violation is based on a racketeering activity for which the maximum penalty includes life imprisonment), or both, and shall forfeit to the United States, irrespective of any provision of State law—"],[1,"(1) any interest the person has acquired or maintained in violation of section 1962;"],[1,"(2) any—"],[2,"(A) interest in;"],[2,"(B) security of;"],[2,"(C) claim against; or"],[2,"(D) property or contractual right of any kind affording a source of influence over;"],[1,"any enterprise which the person has established, operated, controlled, conducted, or participated in the conduct of, in violation of section 1962; and"],[1,"(3) any property constituting, or derived from, any proceeds which the person obtained, directly or indirectly, from racketeering activity or unlawful debt collection in violation of section 1962."],[0,"The court, in imposing sentence on such person shall order, in addition to any other sentence imposed pursuant to this section, that the person forfeit to the United States all property described in this subsection. In lieu of a fine otherwise authorized by this section, a defendant who derives profits or other proceeds from an offense may be fined not more than twice the gross profits or other proceeds."],[0,"(b) Property subject to criminal forfeiture under this section includes—"],[1,"(1) real property, including things growing on, affixed to, and found in land; and"],[1,"(2) tangible and intangible personal property, including rights, privileges, interests, claims, and securities."],[0,"(c) All right, title, and interest in property described in subsection (a) vests in the United States upon the commission of the act giving rise to forfeiture under this section. Any such property that is subsequently transferred to a person other than the defendant may be the subject of a special verdict of forfeiture and thereafter shall be ordered forfeited to the United States, unless the transferee establishes in a hearing pursuant to subsection (l) that he is a bona fide purchaser for value of such property who at the time of purchase was reasonably without cause to believe that the property was subject to forfeiture under this section."],[0,"(d)(1) Upon application of the United States, the court may enter a restraining order or injunction, require the execution of a satisfactory performance bond, or take any other action to preserve the availability of property described in subsection (a) for forfeiture under this section—"],[1,"(A) upon the filing of an indictment or information charging a violation of section 1962 of this chapter and alleging that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section; or"],[1,"(B) prior to the filing of such an indictment or information, if, after notice to persons appearing to have an interest in the property and opportunity for a hearing, the court determines that—"],[2,"(i) there is a substantial probability that the United States will prevail on the issue of forfeiture and that failure to enter the order will result in the property being destroyed, removed from the jurisdiction of the court, or otherwise made unavailable for forfeiture; and"],[2,"(ii) the need to preserve the availability of the property through the entry of the requested order outweighs the hardship on any party against whom the order is to be entered:"],[0,"Provided, however, That an order entered pursuant to subparagraph (B) shall be effective for not more than ninety days, unless extended by the court for good cause shown or unless an indictment or information described in subparagraph (A) has been filed."],[0,"(2) A temporary restraining order under this subsection may be entered upon application of the United States without notice or opportunity for a hearing when an information or indictment has not yet been filed with respect to the property, if the United States demonstrates that there is probable cause to believe that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section and that provision of notice will jeopardize the availability of the property for forfeiture. Such a temporary order shall expire not more than fourteen days after the date on which it is entered, unless extended for good cause shown or unless the party against whom it is entered consents to an extension for a longer period. A hearing requested concerning an order entered under this paragraph shall be held at the earliest possible time, and prior to the expiration of the temporary order."],[0,"(3) The court may receive and consider, at a hearing held pursuant to this subsection, evidence and information that would be inadmissible under the Federal Rules of Evidence."],[0,"(e) Upon conviction of a person under this section, the court shall enter a judgment of forfeiture of the property to the United States and shall also authorize the Attorney General to seize all property ordered forfeited upon such terms and conditions as the court shall deem proper. Following the entry of an order declaring the property forfeited, the court may, upon application of the United States, enter such appropriate restraining orders or injunctions, require the execution of satisfactory performance bonds, appoint receivers, conservators, appraisers, accountants, or trustees, or take any other action to protect the interest of the United States in the property ordered forfeited. Any income accruing to, or derived from, an enterprise or an interest in an enterprise which has been ordered forfeited under this section may be used to offset ordinary and necessary expenses to the enterprise which are required by law, or which are necessary to protect the interests of the United States or third parties."],[0,"(f) Following the seizure of property ordered forfeited under this section, the Attorney General shall direct the disposition of the property by sale or any other commercially feasible means, making due provision for the rights of any innocent persons. Any property right or interest not exercisable by, or transferable for value to, the United States shall expire and shall not revert to the defendant, nor shall the defendant or any person acting in concert with or on behalf of the defendant be eligible to purchase forfeited property at any sale held by the United States. Upon application of a person, other than the defendant or a person acting in concert with or on behalf of the defendant, the court may restrain or stay the sale or disposition of the property pending the conclusion of any appeal of the criminal case giving rise to the forfeiture, if the applicant demonstrates that proceeding with the sale or disposition of the property will result in irreparable injury, harm or loss to him. Notwithstanding 31 U.S.C. 3302(b), the proceeds of any sale or other disposition of property forfeited under this section and any moneys forfeited shall be used to pay all proper expenses for the forfeiture and the sale, including expenses of seizure, maintenance and custody of the property pending its disposition, advertising and court costs. The Attorney General shall deposit in the Treasury any amounts of such proceeds or moneys remaining after the payment of such expenses."],[0,"(g) With respect to property ordered forfeited under this section, the Attorney General is authorized to—"],[1,"(1) grant petitions for mitigation or remission of forfeiture, restore forfeited property to victims of a violation of this chapter, or take any other action to protect the rights of innocent persons which is in the interest of justice and which is not inconsistent with the provisions of this chapter;"],[1,"(2) compromise claims arising under this section;"],[1,"(3) award compensation to persons providing information resulting in a forfeiture under this section;"],[1,"(4) direct the disposition by the United States of all property ordered forfeited under this section by public sale or any other commercially feasible means, making due provision for the rights of innocent persons; and"],[1,"(5) take appropriate measures necessary to safeguard and maintain property ordered forfeited under this section pending its disposition."],[0,"(h) The Attorney General may promulgate regulations with respect to—"],[1,"(1) making reasonable efforts to provide notice to persons who may have an interest in property ordered forfeited under this section;"],[1,"(2) granting petitions for remission or mitigation of forfeiture;"],[1,"(3) the restitution of property to victims of an offense petitioning for remission or mitigation of forfeiture under this chapter;"],[1,"(4) the disposition by the United States of forfeited property by public sale or other commercially feasible means;"],[1,"(5) the maintenance and safekeeping of any property forfeited under this section pending its disposition; and"],[1,"(6) the compromise of claims arising under this chapter."],[0,"Pending the promulgation of such regulations, all provisions of law relating to the disposition of property, or the proceeds from the sale thereof, or the remission or mitigation of forfeitures for violation of the customs laws, and the compromise of claims and the award of compensation to informers in respect of such forfeitures shall apply to forfeitures incurred, or alleged to have been incurred, under the provisions of this section, insofar as applicable and not inconsistent with the provisions hereof. Such duties as are imposed upon the Customs Service or any person with respect to the disposition of property under the customs law shall be performed under this chapter by the Attorney General."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1963?type=usc&year=mostrecent&link-type=html"},"head":"§1963. Criminal penalties","tname":"Crimes and Criminal Procedure","by":{"1":"40, 41","2":"8, 20"}},{"t":"usc","label":"18 U.S.C. § 2510","url":"https://www.law.cornell.edu/uscode/text/18/2510","subs":["(9)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 3486","url":"https://www.law.cornell.edu/uscode/text/18/3486","subs":["(a)(1)(B)"],"by":{"1":"40, 41"}},{"t":"usc","label":"18 U.S.C. § 4130","url":"https://www.law.cornell.edu/uscode/text/18/4130","subs":["(a)"],"by":{"1":"41"}},{"t":"usc","label":"21 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/21/802","subs":["(57)"],"by":{"1":"7, 22"}},{"t":"usc","label":"21 U.S.C. § 851","url":"https://www.law.cornell.edu/uscode/text/21/851","by":{"1":"7"}},{"t":"usc","label":"26 U.S.C. § 104","url":"https://www.law.cornell.edu/uscode/text/26/104","subs":["(a)"],"by":{"1":"41"}},{"t":"usc","label":"26 U.S.C. § 170","url":"https://www.law.cornell.edu/uscode/text/26/170","subs":["(f)(16)(D)"],"stext":{"head":"§170. Charitable, etc., contributions and gifts","paras":[[0,"(a) Allowance of deduction"],[0,"(1) General rule"],[1,"There shall be allowed as a deduction any charitable contribution (as defined in subsection (c)) payment of which is made within the taxable year. A charitable contribution shall be allowable as a deduction only if verified under regulations prescribed by the Secretary."],[0,"(2) Corporations on accrual basis"],[1,"In the case of a corporation reporting its taxable income on the accrual basis, if—"],[2,"(A) the board of directors authorizes a charitable contribution during any taxable year, and"],[2,"(B) payment of such contribution is made after the close of such taxable year and on or before the 15th day of the fourth month following the close of such taxable year,"],[1,"then the taxpayer may elect to treat such contribution as paid during such taxable year. The election may be made only at the time of the filing of the return for such taxable year, and shall be signified in such manner as the Secretary shall by regulations prescribe."],[0,"(3) Future interests in tangible personal property"],[1,"For purposes of this section, payment of a charitable contribution which consists of a future interest in tangible personal property shall be treated as made only when all intervening interests in, and rights to the actual possession or enjoyment of, the property have expired or are held by persons other than the taxpayer or those standing in a relationship to the taxpayer described in section 267(b) or 707(b). For purposes of the preceding sentence, a fixture which is intended to be severed from the real property shall be treated as tangible personal property."],[0,"(b) Percentage limitations"],[0,"(1) Individuals"],[1,"In the case of an individual, the deduction provided in subsection (a) shall be limited as provided in the succeeding subparagraphs."],[0,"(A) General rule"],[2,"Any charitable contribution to—"],[3,"(i) a church or a convention or association of churches,"],[3,"(ii) an educational organization which normally maintains a regular faculty and curriculum and normally has a regularly enrolled body of pupils or students in attendance at the place where its educational activities are regularly carried on,"],[3,"(iii) an organization the principal purpose or functions of which are the providing of medical or hospital care or medical education or medical research, if the organization is a hospital, or if the organization is a medical research organization directly engaged in the continuous active conduct of medical research in conjunction with a hospital, and during the calendar year in which the contribution is made such organization is committed to spend such contributions for such research before January 1 of the fifth calendar year which begins after the date such contribution is made,"],[3,"(iv) an organization which normally receives a substantial part of its support (exclusive of income received in the exercise or performance by such organization of its charitable, educational, or other purpose or function constituting the basis for its exemption under section 501(a)) from the United States or any State or political subdivision thereof or from direct or indirect contributions from the general public, and which is organized and operated exclusively to receive, hold, invest, and administer property and to make expenditures to or for the benefit of a college or university which is an organization referred to in clause (ii) of this subparagraph and which is an agency or instrumentality of a State or political subdivision thereof, or which is owned or operated by a State or political subdivision thereof or by an agency or instrumentality of one or more States or political subdivisions,"],[3,"(v) a governmental unit referred to in subsection (c)(1),"],[3,"(vi) an organization referred to in subsection (c)(2) which normally receives a substantial part of its support (exclusive of income received in the exercise or performance by such organization of its charitable, educational, or other purpose or function constituting the basis for its exemption under section 501(a)) from a governmental unit referred to in subsection (c)(1) or from direct or indirect contributions from the general public,"],[3,"(vii) a private foundation described in subparagraph (F),"],[3,"(viii) an organization described in section 509(a)(2) or (3),"],[3,"(ix) an agricultural research organization directly engaged in the continuous active conduct of agricultural research (as defined in section 1404 of the National Agricultural Research, Extension, and Teaching Policy Act of 1977) in conjunction with a land-grant college or university (as defined in such section) or a non-land grant college of agriculture (as defined in such section), and during the calendar year in which the contribution is made such organization is committed to spend such contribution for such research before January 1 of the fifth calendar year which begins after the date such contribution is made, or"],[3,"(x) an organization described in section 501(c)(19) that is a federally chartered corporation,"],[2,"shall be allowed to the extent that the aggregate of such contributions does not exceed 50 percent of the taxpayer's contribution base for the taxable year."],[0,"(B) Other contributions"],[2,"Any charitable contribution other than a charitable contribution to which subparagraph (A) applies shall be allowed to the extent that the aggregate of such contributions does not exceed the lesser of—"],[3,"(i) 30 percent of the taxpayer's contribution base for the taxable year, or"],[3,"(ii) the excess of 50 percent of the taxpayer's contribution base for the taxable year over the amount of charitable contributions allowable under subparagraph (A) (determined without regard to subparagraph (C))."],[2,"If the aggregate of such contributions exceeds the limitation of the preceding sentence, such excess shall be treated (in a manner consistent with the rules of subsection (d)(1)) as a charitable contribution (to which subparagraph (A) does not apply) in each of the 5 succeeding taxable years in order of time."],[0,"(C) Special limitation with respect to contributions described in subparagraph (A) of certain capital gain property"],[3,"(i) In the case of charitable contributions described in subparagraph (A) of capital gain property to which subsection (e)(1)(B) does not apply, the total amount of contributions of such property which may be taken into account under subsection (a) for any taxable year shall not exceed 30 percent of the taxpayer's contribution base for such year. For purposes of this subsection, contributions of capital gain property to which this subparagraph applies shall be taken into account after all other charitable contributions (other than charitable contributions to which subparagraph (D) applies)."],[3,"(ii) If charitable contributions described in subparagraph (A) of capital gain property to which clause (i) applies exceeds 30 percent of the taxpayer's contribution base for any taxable year, such excess shall be treated, in a manner consistent with the rules of subsection (d)(1), as a charitable contribution of capital gain property to which clause (i) applies in each of the 5 succeeding taxable years in order of time."],[3,"(iii) At the election of the taxpayer (made at such time and in such manner as the Secretary prescribes by regulations), subsection (e)(1) shall apply to all contributions of capital gain property (to which subsection (e)(1)(B) does not otherwise apply) made by the taxpayer during the taxable year. If such an election is made, clauses (i) and (ii) shall not apply to contributions of capital gain property made during the taxable year, and, in applying subsection (d)(1) for such taxable year with respect to contributions of capital gain property made in any prior contribution year for which an election was not made under this clause, such contributions shall be reduced as if subsection (e)(1) had applied to such contributions in the year in which made."],[3,"(iv) For purposes of this paragraph, the term \"capital gain property\" means, with respect to any contribution, any capital asset the sale of which at its fair market value at the time of the contribution would have resulted in gain which would have been long-term capital gain. For purposes of the preceding sentence, any property which is property used in the trade or business (as defined in section 1231(b)) shall be treated as a capital asset."],[0,"(D) Special limitation with respect to contributions of capital gain property to organizations not described in subparagraph (A)"],[0,"(i) In general"],[3,"In the case of charitable contributions (other than charitable contributions to which subparagraph (A) applies) of capital gain property, the total amount of such contributions of such property taken into account under subsection (a) for any taxable year shall not exceed the lesser of—"],[4,"(I) 20 percent of the taxpayer's contribution base for the taxable year, or"],[4,"(II) the excess of 30 percent of the taxpayer's contribution base for the taxable year over the amount of the contributions of capital gain property to which subparagraph (C) applies."],[0,"For purposes of this subsection, contributions of capital gain property to which this subparagraph applies shall be taken into account after all other charitable contributions."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/170?type=usc&year=mostrecent&link-type=html"},"head":"§170. Charitable, etc., contributions and gifts","tname":"Internal Revenue Code","by":{"1":"40, 41","2":"8"}},{"t":"usc","label":"26 U.S.C. § 871","url":"https://www.law.cornell.edu/uscode/text/26/871","subs":["(h)(4)(C)"],"by":{"1":"41"}},{"t":"usc","label":"31 U.S.C. § 9701","url":"https://www.law.cornell.edu/uscode/text/31/9701","subs":["(c)"],"by":{"1":"41"}},{"t":"usc","label":"33 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/33/2241","subs":["(4)","(5)"],"by":{"1":"41, 41"}},{"t":"usc","label":"34 U.S.C. § 20101","url":"https://www.law.cornell.edu/uscode/text/34/20101","subs":["(b)(1)","(f)"],"stext":{"head":"§20101. Crime Victims Fund","paras":[[0,"(a) Establishment"],[0,"There is created in the Treasury a separate account to be known as the Crime Victims Fund (hereinafter in this subchapter referred to as the \"Fund\")."],[0,"(b) Fines deposited in Fund; penalties; forfeited appearance bonds"],[0,"Except as limited by subsection (c), there shall be deposited in the Fund—"],[1,"(1) all fines that are collected from persons convicted of offenses against the United States except—"],[2,"(A) fines available for use by the Secretary of the Treasury pursuant to—"],[3,"(i) section 11(d) of the Endangered Species Act (16 U.S.C. 1540(d)); and"],[3,"(ii) section 6(d) of the Lacey Act Amendments of 1981 (16 U.S.C. 3375(d)); and"],[2,"(B) fines to be paid into—"],[3,"(i) the railroad unemployment insurance account pursuant to the Railroad Unemployment Insurance Act (45 U.S.C. 351 et seq.);"],[3,"(ii) the Postal Service Fund pursuant to sections 2601(a)(2) and 2003 of title 39 and for the purposes set forth in section 404(a)(7) of title 39;"],[3,"(iii) the navigable waters revolving fund pursuant to section 311 of the Federal Water Pollution Control Act (33 U.S.C. 1321); and"],[3,"(iv) county public school funds pursuant to section 3613 of title 18;"],[1,"(2) penalty assessments collected under section 3013 of title 18; 1"],[1,"(3) the proceeds of forfeited appearance bonds, bail bonds, and collateral collected under section 3146 of title 18;"],[1,"(4) any money ordered to be paid into the Fund under section 3671(c)(2) of title 18;"],[1,"(5) any gifts, bequests, or donations to the Fund from private entities or individuals, which the Director is hereby authorized to accept for deposit into the Fund, except that the Director is not hereby authorized to accept any such gift, bequest, or donation that—"],[2,"(A) attaches conditions inconsistent with applicable laws or regulations; or"],[2,"(B) is conditioned upon or would require the expenditure of appropriated funds that are not available to the Office for Victims of Crime; and"],[1,"(6) any funds that would otherwise be deposited in the general fund of the Treasury collected pursuant to—"],[2,"(A) a deferred prosecution agreement; or"],[2,"(B) a non-prosecution agreement."],[0,"(c) Retention of sums in Fund; availability for expenditure without fiscal year limitation"],[0,"Sums deposited in the Fund shall remain in the Fund and be available for expenditure under this subchapter for grants under this subchapter without fiscal year limitation. Notwithstanding subsection (d)(5), all sums deposited in the Fund in any fiscal year that are not made available for obligation by Congress in the subsequent fiscal year shall remain in the Fund for obligation in future fiscal years, without fiscal year limitation."],[0,"(d) Availability for judicial branch administrative costs; grant program percentages"],[0,"The Fund shall be available as follows:"],[1,"(1) Repealed. Pub. L. 105–119, title I, §109(a)(1), Nov. 26, 1997, 111 Stat. 2457."],[1,"(2)(A) Except as provided in subparagraph (B), the first $10,000,000 deposited in the Fund shall be available for grants under section 20104 of this title."],[1,"(B)(i) For any fiscal year for which the amount deposited in the Fund is greater than the amount deposited in the Fund for fiscal year 1998, the $10,000,000 referred to in subparagraph (A) plus an amount equal to 50 percent of the increase in the amount from fiscal year 1998 shall be available for grants under section 20104 of this title."],[1,"(ii) Amounts available under this subparagraph for any fiscal year shall not exceed $20,000,000."],[1,"(3)(A) Of the sums remaining in the Fund in any particular fiscal year after compliance with paragraph (2), such sums as may be necessary shall be available only for—"],[2,"(i) the United States Attorneys Offices and the Federal Bureau of Investigation to provide and improve services for the benefit of crime victims in the Federal criminal justice system (as described in section 3771 or section 3772, as it relates to direct services, of title 18 and section 20141 of this title) through victim coordinators, victims' specialists, and advocates, including for the administrative support of victim coordinators and advocates providing such services; and"],[2,"(ii) a Victim Notification System."],[1,"(B) Amounts made available under subparagraph (A) may not be used for any purpose that is not specified in clause (i) or (ii) of subparagraph (A)."],[1,"(4) Of the remaining amount to be distributed from the Fund in a particular fiscal year—"],[2,"(A) 47.5 percent shall be available for grants under section 20102 of this title;"],[2,"(B) 47.5 percent shall be available for grants under section 20103(a) of this title; and"],[2,"(C) 5 percent shall be available for grants under section 20103(c) of this title."],[1,"(5)(A) In addition to the amounts distributed under paragraphs (2), (3), and (4), the Director may set aside up to $50,000,000 from the amounts transferred to the Fund in response to the airplane hijackings and terrorist acts that occurred on September 11, 2001, as an antiterrorism emergency reserve. The Director may replenish any amounts obligated from such reserve in subsequent fiscal years by setting aside up to 5 percent of the amounts remaining in the Fund in any fiscal year after distributing amounts under paragraphs (2), (3) and (4). Such reserve shall not exceed $50,000,000."],[1,"(B) The antiterrorism emergency reserve referred to in subparagraph (A) may be used for supplemental grants under section 20105 of this title and to provide compensation to victims of international terrorism under section 20106 of this title."],[1,"(C) Amounts in the antiterrorism emergency reserve established pursuant to subparagraph (A) may be carried over from fiscal year to fiscal year. Notwithstanding subsection (c) and section 619 of the Departments of Commerce, Justice, and State, the Judiciary, and Related Agencies Appropriations Act, 2001 (and any similar limitation on Fund obligations in any future Act, unless the same should expressly refer to this section), any such amounts carried over shall not be subject to any limitation on obligations from amounts deposited to or available in the Fund."],[1,"(6)(A) The Director may set aside up to $10,000,000 of the amounts remaining in the Fund in any fiscal year after distributing the amounts under paragraphs (2), (3), and (4), in a Child Pornography Victims Reserve, which may be used by the Attorney General for payments under section 2259(d) of title 18."],[1,"(B) Amounts in the reserve may be carried over from fiscal year to fiscal year, but the total amount of the reserve shall not exceed $10,000,000. Notwithstanding subsection (c) and any limitation on Fund obligations in any future Act, unless the same should expressly refer to this section, any such amounts carried over shall not be subject to any limitation on obligations from amounts deposited to or available in the Fund."],[0,"(e) Amounts awarded and unspent"],[0,"Any amount awarded as part of a grant under this subchapter that remains unspent at the end of a fiscal year in which the grant is made may be expended for the purpose for which the grant is made at any time during the 3 succeeding fiscal years, at the end of which period, any remaining unobligated sums shall be available for deposit into the emergency reserve fund referred to in subsection (d)(5) at the discretion of the Director, except that renewals and extensions beyond that period may be granted at the discretion of the Attorney General. Any remaining unobligated sums shall be returned to the Fund."],[0,"(f) \"Offenses against the United States\" as excluding"],[0,"As used in this section, the term \"offenses against the United States\" does not include—"],[1,"(1) a criminal violation of the Uniform Code of Military Justice (10 U.S.C. 801 et seq.);"],[1,"(2) an offense against the laws of the District of Columbia; and"],[1,"(3) an offense triable by an Indian tribal court or Court of Indian Offenses."],[0,"(g) Grants for Indian tribes; child abuse cases"],[0,"(1) The Attorney General shall use 15 percent of the funds available under subsection (d)(2) to make grants for the purpose of assisting Native American Indian tribes in developing, establishing, and operating programs designed to improve—"],[1,"(A) the handling of child abuse cases, particularly cases of child sexual abuse, in a manner which limits additional trauma to the child victim; and"],[1,"(B) the investigation and prosecution of cases of child abuse, particularly child sexual abuse."],[0,"(2) The Attorney General may use 5 percent of the funds available under subsection (d)(2) (prior to distribution) for grants to Indian tribes to establish child victim assistance programs, as appropriate."],[0,"(3) As used in this subsection, the term \"tribe\" 2 has the meaning given that term in section 5304(b) 1 of title 25."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/34/20101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§20101. Crime Victims Fund","tname":"Crime Control and Law Enforcement","by":{"1":"17, 17, 38","2":"8, 11"}},{"t":"usc","label":"38 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/38/511","subs":["(b)"],"by":{"1":"41"}},{"t":"usc","label":"45 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/45/231","subs":["(a)(2)"],"by":{"1":"41"}},{"t":"usc","label":"46 U.S.C. § 8103","url":"https://www.law.cornell.edu/uscode/text/46/8103","subs":["(b)(2)"],"by":{"1":"41"}},{"t":"usc","label":"49 U.S.C. § 28301","url":"https://www.law.cornell.edu/uscode/text/49/28301","subs":["(b)(1)"],"by":{"1":"41"}},{"t":"usc","label":"52 U.S.C. § 30118","url":"https://www.law.cornell.edu/uscode/text/52/30118","subs":["(b)(2)"],"by":{"1":"41"}},{"t":"reg","label":"88 Fed. Reg. 7186","url":"https://www.govinfo.gov/link/fr/88/7186","by":{"1":"45"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"143 S. Ct. 665","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"10"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21"}},{"t":"case","label":"Mills Music, Inc. v. Snyder","cite":"469 U.S. 153","y":1985,"id":"1984/83-1153","sc":1,"sum":"This case involves a controversy between petitioner publisher and respondent heirs of the author of the 1923 copyrighted song \"Who's Sorry Now\" over the division of royalty income that the sound recordings of the song have generated. In 1940, the author assigned his entire interest in all renewals of the copyright to petitioner in exchange for an advance royalty and petitioner's commitment to pay a cash royalty on …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Mount Lemmon Fire District v. Guido","cite":"139 S. Ct. 22","y":2018,"id":"2018/17-587","sc":1,"sum":"State and local governments are covered employers under the Age Discrimination in Employment Act of 1967 regardless of the number of employees they have.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"7"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Slack Technologies, LLC v. Pirani","cite":"143 S. Ct. 1433","y":2023,"id":"2022/22-200","sc":1,"sum":"To state a claim under §11(a) of the Securities Act of 1933, a plaintiff must allege the purchase of “such security” issued pursuant to a materially misleading registration statement.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20, 21"}},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"op":1,"sum":"A defendant convicted of violating § 922 (h) is properly sentenced under § 924 (a) even though his conduct also violates § 1202 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4, 23"}},{"t":"case","label":"United States v. Owens","cite":"38 F.4th 1","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/1/","by":{"2":"22"}},{"t":"case","label":"United States v. Quirante","cite":"486 F.3d 1273","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/486/1273/","by":{"2":"22"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"2":"8"}},{"t":"const","label":"Article I, Section 8, Clause 10","text":"To define and punish Piracies and Felonies committed on the high Seas, and Offences against the Law of Nations;","by":{"2":"8"}},{"t":"const","label":"Article I, Section 8, Clause 11","clauses":[["war-powers","War Powers Clause"]],"text":"To declare War, grant Letters of Marque and Reprisal, and make Rules concerning Captures on Land and Water;","by":{"2":"8, 11"}}]};